from ukgen import *
from msvg import C as Canvas, tag

GEN = {'ч': 'чоловічого', 'ж': 'жіночого', 'с': 'середнього'}
NOUNS = {'ч': 'біль степ дріб тюль олень кінь бульвар шампунь рояль кашель ячмінь ювілей дощ сир'.split(),
         'ж': 'сіль мозоль вуаль тополя радість ніч подорож розкіш лють кров осінь річ тінь ластівка'.split(),
         'с': "плем'я ім'я теля курча поле бюро радіо кафе метро таксі пальто кіно інтерв'ю".split()}
HARD = {'ч': 'біль степ дріб тюль шампунь рояль кашель ячмінь'.split(), 'ж': 'сіль мозоль вуаль подорож розкіш лють кров осінь'.split(), 'с': 'кафе метро таксі пальто бюро інтерв\'ю'.split()}
def f_gender(T, rng, lv):
    g = rng.choice('чжс')
    pool = (HARD[g] if lv >= 2 else NOUNS[g]); w = rng.choice(pool)
    ds = []
    for og in rng.sample([x for x in 'чжс' if x != g], 2):
        ds.append((rng.choice(HARD[og] if lv >= 2 else NOUNS[og]), og))
    og = rng.choice('чжс'); ds.append((rng.choice([x for x in (HARD[og] if lv >= 2 else NOUNS[og]) if x != w and x not in [d[0] for d in ds]]), og))
    if len({d[1] for d in ds} - {g}) == 0: return False
    wr = [(d, f'іменник {GEN[og][:-3]}ого роду' if False else f'це іменник {GEN[og]} роду') for d, og in ds if og != g]
    wr = [(d, f'це іменник {GEN[o]} роду') for d, o in ds if o != g]
    if len(wr) < 3: return False
    return T.add(lv, f'Укажіть іменник {GEN[g]} роду.', w, wr, 'закінчення -ь і неозначувані слова не визначають рід однозначно', f'{w} — іменник {GEN[g]} роду')
COMMON = ['плакса', 'ябеда', 'нероба', 'сирота', 'роззява', 'бідолаха']
def f_common(T, rng, lv):
    w = rng.choice(COMMON); ds = rng.sample(NOUNS['ч'] + NOUNS['ж'], 3)
    wr = [(d, f'іменник {"чоловічого" if d in NOUNS["ч"] else "жіночого"} роду, не спільного') for d in ds]
    return T.add(lv, 'Укажіть іменник спільного роду.', w, wr, 'спільний рід — слово може означати і чоловіка, і жінку (він плакса, вона плакса)', f'{w} — іменник спільного роду: він {w}, вона {w}')

QW = {'Н': 'хто? що?', 'Р': 'кого? чого?', 'Д': 'кому? чому?', 'З': 'кого? що?', 'О': 'ким? чим?', 'М': 'на кому? на чому?', 'К': 'звертання'}
CN = {'Н': 'називний', 'Р': 'родовий', 'Д': 'давальний', 'З': 'знахідний', 'О': 'орудний', 'М': 'місцевий', 'К': 'кличний'}
CASES = [("Сестра читає цікаву книжку.", "книжку", 'З'), ("Брат допомагає батьку.", "батьку", 'Д'), ("Ми були в лісі.", "лісі", 'М'), ("Діти малюють олівцем.", "олівцем", 'О'),
 ("У кошику немає яблук.", "яблук", 'Р'), ("Мамо, допоможи мені!", "Мамо", 'К'), ("Учень написав листа.", "листа", 'З'), ("Я дякую вчителеві.", "вчителеві", 'Д'), ("Школа стоїть за містом.", "школа", 'Н'),
 ("Він пишається сином.", "сином", 'О'), ("Ми йшли до річки.", "річки", 'Р'), ("На столі лежить зошит.", "столі", 'М'), ("Подруго, приходь!", "Подруго", 'К'), ("Дівчина співає пісню.", "пісню", 'З'),
 ("Ми живемо в Україні.", "Україні", 'М'), ("Туристи милуються горами.", "горами", 'О'), ("Я надіслав листа другові.", "другові", 'Д'), ("Біля будинку росте дерево.", "будинку", 'Р'),
 ("Сьогодні холодний вітер.", "вітер", 'Н'), ("Друже, ходімо з нами!", "Друже", 'К'), ("Ми їхали з бабусею.", "бабусею", 'О'), ("Він сидів на стільці.", "стільці", 'М'), ("Подарунок для мами.", "мами", 'Р'),
 ("Вона дзвонить сестрі.", "сестрі", 'Д'), ("Дерева шумлять під вітром.", "вітром", 'О')]
def f_case(T, rng, lv):
    s, w, c = rng.choice(CASES)
    pool = [x for x in 'НРДЗОМК' if x != c]
    ds = rng.sample(pool, 3 if lv < 3 else 4)
    wr = [(CN[x], f'у цьому відмінку іменник відповідає на питання «{QW[x]}»; а «{w}» відповідає на «{QW[c]}»') for x in ds]
    return T.add(lv, f'У якому відмінку вжито іменник «{w}» у реченні «{s}»?', CN[c], wr, 'орудний і давальний відмінки легко сплутати за закінченням; орієнтуйся на питання', f'«{w}» відповідає на питання «{QW[c]}» — {CN[c]} відмінок')

DECL = {'мама': ('мама', 'мами', 'мамі', 'маму', 'мамою', 'мамі'), 'книга': ('книга', 'книги', 'книзі', 'книгу', 'книгою', 'книзі'), 'сестра': ('сестра', 'сестри', 'сестрі', 'сестру', 'сестрою', 'сестрі'),
        'дорога': ('дорога', 'дороги', 'дорозі', 'дорогу', 'дорогою', 'дорозі'), 'ластівка': ('ластівка', 'ластівки', 'ластівці', 'ластівку', 'ластівкою', 'ластівці'),
        'ріка': ('ріка', 'ріки', 'ріці', 'ріку', 'рікою', 'ріці'), 'нога': ('нога', 'ноги', 'нозі', 'ногу', 'ногою', 'нозі'), 'вода': ('вода', 'води', 'воді', 'воду', 'водою', 'воді'),
        'школа': ('школа', 'школи', 'школі', 'школу', 'школою', 'школі'), 'квітка': ('квітка', 'квітки', 'квітці', 'квітку', 'квіткою', 'квітці'), 'країна': ('країна', 'країни', 'країні', 'країну', 'країною', 'країні'),
        'рука': ('рука', 'руки', 'руці', 'руку', 'рукою', 'руці')}
ORDER = 'НРДЗОМ'
PREP = {'мама': 'на', 'книга': 'на', 'сестра': 'біля', 'дорога': 'на', 'ластівка': 'на', 'ріка': 'на', 'нога': 'на', 'вода': 'у', 'школа': 'у', 'квітка': 'на', 'країна': 'у', 'рука': 'на'}
def draw_decl(noun, idx, order):
    forms = DECL[noun]
    labels = []
    for pos, ci in enumerate(order):
        f = forms[ci]
        if ORDER[ci] == 'М': f = f'({PREP[noun]}) ' + f
        labels.append(f)
    c = Canvas(520, 215, f'Відмінкові форми іменника «{noun}»')
    c.text(260, 44, 'форми подано у довільному порядку', size=12, anchor='middle', col='#6b7280')
    for pos, ci in enumerate(order):
        col, row = pos % 2, pos // 2
        x = 40 + col * 230; y = 62 + row * 46
        hl = (ci == idx)
        c.rect(x, y, 210, 36, fill='#fef08a' if hl else '#f3f4f6', stroke='#ca8a04' if hl else '#9ca3af', sw=3 if hl else 1.5, rx=8)
        c.text(x + 105, y + 24, labels[pos], size=17, anchor='middle', bold=hl)
    name = f'u5_{tag(noun, idx, order)}'
    open(f'{IMGDIR}/{name}.svg', 'w', encoding='utf-8').write(c.svg())
    return f'/img/ukrainian/{name}.svg'
def f_img_case(T, rng, lv):
    n = rng.choice(list(DECL)); order = list(range(6)); rng.shuffle(order)
    idx = rng.randrange(6); form = DECL[n][idx]
    # якщо форма співпадає з іншою у таблиці, Д/М розрізняються приписаним прийменником
    ds = [x for x in range(6) if x != idx]
    ds = rng.sample(ds, 3 if lv < 3 else 4)
    wr = [(CN[ORDER[x]], f'форма «{(DECL[n][x] if ORDER[x] != "М" else "на " + DECL[n][x])}» стоїть у відмінку «{CN[ORDER[x]]}», а виділена — в іншому') for x in ds]
    wr = [(CN[ORDER[x]], f'у цьому відмінку іменник «{n}» має форму «{DECL[n][x]}»' + (' (з прийменником ' + PREP[n] + ')' if ORDER[x] == 'М' else '')) for x in ds]
    img = draw_decl(n, idx, order)
    shown = (PREP[n] + ' ' if ORDER[idx] == 'М' else '') + form
    return T.add(lv, f'На малюнку подано відмінкові форми іменника «{n}». У якому відмінку стоїть виділена форма?', CN[ORDER[idx]], wr, 'у давальному й місцевому відмінках форми можуть збігатися, відрізняйте за питанням і прийменником', f'форма «{shown}» відповідає на питання «{QW[ORDER[idx]]}»', img=img)

DECLN = {'І': 'мама вода пісня земля надія тато зоря'.split(), 'ІІ': 'стіл кінь ліс поле село вікно гай море дядько'.split(), 'ІІІ': 'ніч любов радість осінь мати тінь сіль річ розкіш'.split(), 'ІV': "теля кошеня ім'я плем'я курча лоша дівча щеня".split()}
DREASON = {'І': 'іменники І відміни закінчуються на -а, -я', 'ІІ': 'іменники ІІ відміни — чоловічого роду з нульовим закінченням або середнього роду на -о, -е', 'ІІІ': 'іменники ІІІ відміни — жіночого роду на приголосний або -ь', 'ІV': 'іменники IV відміни — назви малят на -а, -я та слова ім’я, плем’я'}
def f_declension(T, rng, lv):
    d = rng.choice(list(DECLN)); w = rng.choice(DECLN[d])
    if d == 'І' and w == 'тато' and lv == 1: pass
    wr = [(f'{x} відміна', f'іменники {x} відміни: {DREASON[x]}') for x in DECLN if x != d]
    if lv >= 3: wr.append(('належить до іменників, що не відмінюються', 'це слово відмінюється'))
    return T.add(lv, f'До якої відміни належить іменник «{w}»?', f'{d} відміна', [(a, f'для «{w}» це не так: {r}') for a, r in wr], 'відміну визначаємо за закінченням у називному відмінку і за родом', f'{w}: {DREASON[d]}')
def f_declension_row(T, rng, lv):
    d = rng.choice(list(DECLN)); ws = rng.sample(DECLN[d], 3)
    others = [(x, w) for x in DECLN if x != d for w in DECLN[x]]
    ls = [(', '.join(ws), None)]
    for k in range(3):
        a, b = rng.sample(ws, 2); od, ow = rng.choice(others)
        xs = [a, b, ow]; rng.shuffle(xs)
        ls.append((', '.join(xs), f'«{ow}» належить до {od} відміни'))
    return T.add(lv, f'У якому рядку всі іменники належать до {d} відміни?', ls[0][0], ls[1:], 'один «чужий» іменник у рядку легко проґавити', DREASON[d])

TENS = {20: ('двадцять', 'двадцяти'), 30: ('тридцять', 'тридцяти'), 40: ('сорок', 'сорока'), 50: ("п'ятдесят", "п'ятдесяти"), 60: ('шістдесят', 'шістдесяти'), 70: ('сімдесят', 'сімдесяти'), 80: ('вісімдесят', 'вісімдесяти')}
UN = {2: ('два', 'двох'), 3: ('три', 'трьох'), 4: ('чотири', 'чотирьох'), 5: ("п'ять", "п'яти"), 6: ('шість', 'шести'), 7: ('сім', 'семи'), 8: ('вісім', 'восьми'), 9: ("дев'ять", "дев'яти")}
FR = ['У залі немає {} місць.', 'Біля школи стоїть не більше {} автомобілів.', 'У класі не вистачає {} підручників.']
def f_num(T, rng, lv):
    t = rng.choice(list(TENS)); u = rng.choice(list(UN)); n = t + u
    ok = f'{TENS[t][1]} {UN[u][1]}'
    wr = [(f'{TENS[t][0]} {UN[u][1]}', 'не змінено першу частину складеного числівника'), (f'{TENS[t][1]} {UN[u][0]}', 'не змінено другу частину складеного числівника'), (f'{TENS[t][0]} {UN[u][0]}', 'числівник узагалі не змінено')]
    return T.add(lv, f'Укажіть правильну форму числівника ({n}) у реченні: «' + rng.choice(FR).replace('{}', '…') + '»', ok, wr, 'у складених кількісних числівниках змінюються всі слова', 'складений числівник відмінюємо повністю: кожну частину')

ADJ = [('великий', 'більший', 'найбільший'), ('малий', 'менший', 'найменший'), ('поганий', 'гірший', 'найгірший'), ('добрий', 'кращий', 'найкращий'), ('високий', 'вищий', 'найвищий'), ('низький', 'нижчий', 'найнижчий'),
       ('глибокий', 'глибший', 'найглибший'), ('тонкий', 'тонший', 'найтонший'), ('легкий', 'легший', 'найлегший'), ('широкий', 'ширший', 'найширший'), ('короткий', 'коротший', 'найкоротший'), ('довгий', 'довший', 'найдовший'),
       ('молодий', 'молодший', 'наймолодший'), ('старий', 'старший', 'найстарший')]
def f_degree(T, rng, lv):
    p, c, s = rng.choice(ADJ)
    if rng.random() < .5:
        wr = [(f'більш {c}', 'змішано просту й складену форми: «більш» додають лише до звичайної форми прикметника'), (f'найбільш {c}', 'змішано просту й складену форми'), (f'самий {p[:-2]}ий' if False else f'самий {p}', 'слово «самий» не утворює ступенів порівняння')]
        return T.add(lv, f'Укажіть правильну форму вищого ступеня порівняння від прикметника «{p}».', c, wr, 'складену форму утворюють додаванням «більш» до початкової форми, а не до вищого ступеня', f'проста форма вищого ступеня: {c}')
    wr = [(f'більш {s}', 'змішано просту й складену форми'), (f'найбільш {s}', 'змішано просту й складену форми'), (f'самий {p}', 'слово «самий» не утворює ступенів порівняння')]
    return T.add(lv, f'Укажіть правильну просту форму найвищого ступеня порівняння від прикметника «{p}».', s, wr, 'найвищий ступінь має префікс най-, а не додаткові слова', f'проста форма найвищого ступеня: {s}')

PRON = {'особовий': ['я', 'ти', 'він', 'вона', 'ми', 'вони'], 'зворотний': ['себе'], 'питальний': ['хто', 'що', 'який', 'чий', 'котрий'], 'неозначений': ['хтось', 'дехто', 'щось', 'будь-хто', 'казна-що', 'якийсь', 'деякий'],
        'заперечний': ['ніхто', 'ніщо', 'ніякий', 'нічий', 'ніякий'], 'вказівний': ['цей', 'той', 'такий', 'стільки'], 'означальний': ['весь', 'сам', 'кожен', 'інший', 'усякий'], 'присвійний': ['мій', 'твій', 'наш', 'ваш', 'свій']}
PRON['питальний'] = ['хто', 'що', 'який', 'чий', 'котрий']
def f_pron(T, rng, lv):
    k = rng.choice(['неозначений', 'заперечний', 'вказівний', 'означальний', 'присвійний', 'особовий'])
    w = rng.choice(PRON[k]); others = [x for x in PRON if x != k]
    wr = [(rng.choice(PRON[x]), f'це {x} займенник') for x in rng.sample(others, 3)]
    return T.add(lv, f'Укажіть {k} займенник.', w, wr, 'розряди займенників розрізняй за значенням і за ознаками словотвору (ні-, будь-, -сь, казна-)', f'«{w}» — {k} займенник')

ASP = [('писати', 'написати'), ('читати', 'прочитати'), ('будувати', 'збудувати'), ('робити', 'зробити'), ('малювати', 'намалювати'), ('вчити', 'вивчити'), ('купувати', 'купити'), ('давати', 'дати'), ('брати', 'взяти'),
       ('говорити', 'сказати'), ('ставити', 'поставити'), ('приходити', 'прийти'), ('лягати', 'лягти'), ('відкривати', 'відкрити')]
def f_aspect(T, rng, lv):
    a, b = rng.choice(ASP)
    if rng.random() < .5:
        ds = [x[0] for x in rng.sample([p for p in ASP if p != (a, b)], 3)]
        return T.add(lv, 'Укажіть дієслово доконаного виду.', b, [(d, 'відповідає на питання «що робити?» — недоконаний вид') for d in ds], 'доконаний вид відповідає на питання «що зробити?»', f'«{b}» — що зробити? — доконаний вид')
    ds = [x[1] for x in rng.sample([p for p in ASP if p != (a, b)], 3)]
    return T.add(lv, 'Укажіть дієслово недоконаного виду.', a, [(d, 'відповідає на питання «що зробити?» — доконаний вид') for d in ds], 'недоконаний вид відповідає на питання «що робити?»', f'«{a}» — що робити? — недоконаний вид')

CONJ = {'I': [('писати', 'пишеш'), ('читати', 'читаєш'), ('працювати', 'працюєш'), ('малювати', 'малюєш'), ('знати', 'знаєш'), ('співати', 'співаєш'), ('брати', 'береш')],
        'II': [('говорити', 'говориш'), ('бачити', 'бачиш'), ('любити', 'любиш'), ('лежати', 'лежиш'), ('кричати', 'кричиш'), ('учити', 'учиш'), ('носити', 'носиш'), ('мовчати', 'мовчиш'), ('стояти', 'стоїш'), ('спати', 'спиш')]}
def f_conj(T, rng, lv):
    k = rng.choice(['I', 'II']); o = 'II' if k == 'I' else 'I'
    pool = CONJ[k] if lv >= 2 else [x for x in CONJ[k] if x[0] not in ('стояти', 'спати', 'брати')]
    w, f2 = rng.choice(pool)
    ds = rng.sample(CONJ[o], 3)
    return T.add(lv, f'Укажіть дієслово {k} дієвідміни.', w, [(d[0], f'форма 2-ї особи однини «{d[1]}» — {o} дієвідміна') for d in ds], 'дієвідміну визначаємо за формою 2-ї особи однини, а не за інфінітивом', f'форма 2-ї особи однини «{f2}» — {k} дієвідміна')

PART = {'дієприслівник': ['читаючи', 'прочитавши', 'працюючи', 'написавши', 'сміючись', 'гуляючи'], 'інфінітив': ['читати', 'писати', 'працювати', 'сміятися'], 'дієприкметник': ['прочитаний', 'написаний', 'зламаний', 'збудований'], 'прикметник': ['читальний', 'письмовий', 'робочий', 'зламаний'][:3]}
PQ = {'дієприслівник': 'що роблячи? що зробивши?', 'інфінітив': 'що робити? що зробити?', 'дієприкметник': 'який? (від дієслова)', 'прикметник': 'який?'}
def f_part(T, rng, lv):
    k = rng.choice(['дієприслівник', 'дієприкметник', 'інфінітив']); w = rng.choice(PART[k])
    ds = [(rng.choice(PART[x]), x) for x in rng.sample([y for y in PART if y != k and y != 'прикметник'], 2)]
    ds.append((rng.choice(PART['прикметник']), 'прикметник'))
    return T.add(lv, f'Укажіть {k}.', w, [(d, f'це {x}: {PQ[x]}') for d, x in ds], 'дієприслівник відповідає на питання «що роблячи?», а не «який?»', f'«{w}» — {k}: {PQ[k]}')

POS = {'іменник': ['радість', 'вчитель', 'подорож', 'сестра', 'море'], 'прикметник': ['добрий', 'гарний', 'червоний', 'високий'], 'дієслово': ['читати', 'бігти', 'працюють', 'співає'],
       'прислівник': ['швидко', 'вдома', 'учора', 'завтра', 'скрізь', 'ніколи', 'тут'], 'займенник': ['мій', 'вони', 'хто', 'ніхто', 'цей', 'який'], 'числівник': ["п'ять", 'перший', 'двоє', 'сорок', 'сто'],
       'прийменник': ['на', 'біля', 'через', 'між', 'крізь', 'понад', 'для'], 'сполучник': ['і', 'але', 'щоб', 'якщо', 'бо', 'проте'], 'частка': ['не', 'хай', 'хіба', 'навіть', 'лише'], 'вигук': ['ой', 'ах', 'гей', 'ого', 'ох']}
def f_pos(T, rng, lv):
    k = rng.choice(['прислівник', 'прийменник', 'сполучник', 'частка', 'вигук', 'числівник', 'займенник'] if lv >= 2 else ['іменник', 'прикметник', 'дієслово', 'прислівник', 'числівник'])
    w = rng.choice(POS[k]); others = [x for x in POS if x != k]
    q = f'Яке з поданих слів є {({"прислівник":"прислівником","прийменник":"прийменником","сполучник":"сполучником","частка":"часткою","вигук":"вигуком","числівник":"числівником","займенник":"займенником","іменник":"іменником","прикметник":"прикметником","дієслово":"дієсловом"})[k]}?'
    return T.add(lv, q, w, [(rng.choice(POS[x]), f'це {x}') for x in rng.sample(others, 3)], 'службові слова (прийменник, сполучник, частка) не є членами речення', f'«{w}» — {k}')
def f_pos_row(T, rng, lv):
    k = rng.choice(['прислівник', 'прийменник', 'сполучник', 'займенник', 'числівник'])
    ws = rng.sample(POS[k], 3); others = [(x, w) for x in POS if x != k for w in POS[x]]
    ls = [(', '.join(ws), None)]
    for i in range(3):
        a, b = rng.sample(ws, 2); od, ow = rng.choice(others); xs = [a, b, ow]; rng.shuffle(xs)
        ls.append((', '.join(xs), f'«{ow}» — {od}, а не {k}'))
    return T.add(lv, f'У якому рядку всі слова є частиною мови «{k}»?', ls[0][0], ls[1:], 'один «чужий» член ряду легко проґавити', f'усі три слова — {k}и')

VOC = [('Іван', 'Іване', 'для іменників на -ан закінчення -е', ['Івану', 'Івана']), ('Андрій', 'Андрію', 'для іменників на -ій закінчення -ю', ['Андрій', 'Андрія']), ('друг', 'друже', 'г чергується з ж: друже', ['друга', 'другу']),
       ('син', 'сину', 'для іменників на -ин закінчення -у', ['сина', 'сини']), ('учитель', 'учителю', 'для м’яких основ закінчення -ю', ['учителя', 'учителі']), ('мама', 'мамо', 'для іменників на -а закінчення -о', ['мами', 'мамі']),
       ('сестра', 'сестро', 'для іменників на -а закінчення -о', ['сестри', 'сестрі']), ('Олена', 'Олено', 'для іменників на -а закінчення -о', ['Олени', 'Олені']), ('Марія', 'Маріє', 'для іменників на -ія закінчення -є', ['Марії', 'Марію']),
       ('пан', 'пане', 'для іменників на -ан закінчення -е', ['пану', 'пана'])]
def f_voc(T, rng, lv):
    n, v, why, alt = rng.choice(VOC)
    wr = [(n, 'це називний відмінок: звертання вимагає кличного')] + [(a, 'це форма іншого відмінка, а не кличного') for a in alt]
    return T.add(lv, f'Укажіть правильну форму кличного відмінка іменника «{n}».', v, wr, 'закінчення кличного залежить від основи слова', why)

